package mrpapermoon.whisper.screenimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.material.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.LaunchedEffectimport androidx.compose.runtime.collectAsStateimport androidx.compose.runtime.derivedStateOfimport androidx.compose.runtime.getValueimport androidx.compose.runtime.rememberimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.layout.layoutimport androidx.compose.ui.tooling.preview.Previewimport androidx.compose.ui.unit.dpimport androidx.hilt.lifecycle.viewmodel.compose.hiltViewModelimport mrpapermoon.whisper.actors.MeshActionimport mrpapermoon.whisper.actors.MeshStateimport mrpapermoon.whisper.navigation.LocalNavigationActionimport mrpapermoon.whisper.navigation.NavigationScreenimport mrpapermoon.whisper.ui.theme.WhisperColorsimport mrpapermoon.whisper.ui.theme.WhisperThemeimport mrpapermoon.whisper.ui.widget.BrandBackgroundimport mrpapermoon.whisper.ui.widget.WhisperWaveBar@Composablefun SplashScreen(	isReady: Boolean,	modifier: Modifier = Modifier,	splashViewModel: SplashViewModel = hiltViewModel(),) {	val navigationAction = LocalNavigationAction.current	val meshState by splashViewModel.meshState.collectAsState()	val statusText by remember(meshState, isReady) {		derivedStateOf {			if (isReady) {				when (val state = meshState) {					is MeshState.Idle -> "Initializing..."					is MeshState.Initializing -> "Initializing Mesh Engine..."					is MeshState.Ready -> "Started collecting rumors"					is MeshState.Error -> "Error: ${state.errorMessage}"				}			} else {				null			}		}	}	BrandBackground(modifier = modifier, padding = 16.dp) {		SplashScreen(statusText.orEmpty())	}	LaunchedEffect(isReady) {		splashViewModel.sendAction(MeshAction.Initialize)	}	LaunchedEffect(meshState) {		if (meshState is MeshState.Ready) {			navigationAction.navigateTo(NavigationScreen.main)		}	}}@Composableprivate fun SplashScreen(status: String) {	Column(		modifier = Modifier			.padding(horizontal = 4.dp)			.layout { measurable, constraints ->				val placeable = measurable.measure(constraints)				val baselineY = (constraints.maxHeight * 3) / 4				val x = (constraints.maxWidth - placeable.width) / 2				val y = (baselineY - placeable.height).coerceAtLeast(0)				layout(constraints.maxWidth, constraints.maxHeight) {					placeable.placeRelative(x, y)				}			},		verticalArrangement = Arrangement.spacedBy(2.dp),		horizontalAlignment = Alignment.CenterHorizontally,	) {		Text(status)		WhisperWaveBar(			modifier = Modifier.fillMaxWidth(),			waveColor = WhisperColors.primary_200,			strokeWidth = 2.dp,		)	}}@Preview@Composablefun SplashScreenPreview() {	WhisperTheme {		BrandBackground(padding = 16.dp) {			SplashScreen("Initializing...")		}	}}